userscript.function:

voOriginalGridObj.attachEvent("onBeforeContextMenu", () =>{
    return false;
});

voOriginalGridObj.attachEvent("onHeaderClick", () => {
    return false;
});

voOriginalGridObj.attachEvent("onRowDblClicked", (rId, cInd) => {
    voOriginalGridObj.selectRow(rId);
    doAddColumn(false);
});

voCustomGridObj.attachEvent("onBeforeContextMenu", ()=>{
    return false;
});

voCustomGridObj.attachEvent("onHeaderClick", () => {
    return false;
});

voCustomGridObj.attachEvent("onRowDblClicked", (rId, cInd) => {
    voCustomGridObj.selectRow(rId);
    doClearColumn(false);
});

voOriginalGridObj.disableHeaderFilter();
voCustomGridObj.disableHeaderFilter();

callFunction('GP_003', 'setObj', ['VIEW_ORDER', voOriginalGridObj]);
callFunction('GP_003', 'setObj', ['CUSTOM', voCustomGridObj]);


voOriginalGridObj.clearAll();

var colIds = $share.gridObj.grid_col_id;
var hiddenColumn = [];
var showColumn = [];

if(colIds.length > 0) {
    $share.original = [];
    var cspanIds = [];
    var cspanEndId = undefined;
    for(var i = 0; i < colIds.length; i++) {
        var colId = colIds[i];
        var colIndex = $share.gridObj.getColIndexById(colId);
        var maxRowId = i + 1;
        var align = $share.gridObj.grid_col_align[colIndex] === undefined ? 'left' : $share.gridObj.grid_col_align[colIndex];
        var type = $share.gridObj.getColType(colIndex) === undefined ? 'ro' : $share.gridObj.getColType(colIndex);
        var isCspan = false;

        if($share.gridObj.grid_header[i] == '#cspan') {
            isCspan = true;
            if(!cspanIds.includes(colId)) {
                for(var j = i; j < colIds.length; j++) {
                    var cspanId = colIds[j];
                    var cspanName = $share.gridObj.grid_header[j];
                    if(cspanName != '#cspan') {
                        break;
                    }

                    cspanEndId = j;
                    cspanIds.push(cspanId);
                }
            }

            if(i == cspanEndId) {
                voOriginalGridObj.cells(maxRowId - cspanIds.length, voOriginalGridObj.getColIndexById('CSPAN')).setValue(cspanIds.join(','));
                cspanIds = [];
                cspanEndId = undefined;
            }
        }

        var obj = {
            COLUMN_NAME : $share.gridObj.grid_header[i],
            COLUMN_ID : colId,
            TYPE : type,
            ALIGN : align,
            STANDARD_WIDTH : parseInt($share.gridObj.grid_init_widths[colIndex]),
            FREEZE : false,
            IS_CSPAN : isCspan
        };

        $share.original.push(obj);
        callFunction('GP_003', 'addData', [voOriginalGridObj, maxRowId, voOriginalGridObj.getRowsNum(), obj, false, isCspan]);

        if($share.gridObj.isColumnHidden(colIndex) == true) {
            hiddenColumn.push(obj);
        } else {
            showColumn.push(obj);
        }
    }

    const oData = voOriginalGridObj.getAllDataObject();
    var headerData = [];

    if(flag == false && jsonData != undefined) {
        const headers = jsonData.headers.filter(x => x.hidden == false);
        var freezeColId = jsonData.freeze;
        var freezeRowId;

        for(var header of headers) {
            var columnIndex = $share.gridObj.getColIndexById(header.id);
            var hData = oData.filter(x => x.COLUMN_ID == header.id)[0];
            var rowId = hData.gr_id;
            var itemIndex = voCustomGridObj.getRowsNum();
            var freezeFlag = false;
            var cspanFlag = false;

            if(header.id == freezeColId) {
                freezeFlag = true;

                if(header.label == '#cspan') {
                    var parent = oData.filter(x => x.CSPAN.includes(header.id));
                    if(parent.length > 0) {
                        freezeRowId = parent[0].gr_id;
                    }
                } else {
                    freezeRowId = rowId;
                }
            }

            var obj = {
                COLUMN_NAME : header.label,
                COLUMN_ID : header.id,
                TYPE : $share.gridObj.getColType(columnIndex),
                ALIGN : $share.gridObj.cellAlign[columnIndex],
                STANDARD_WIDTH : $share.gridObj.getColWidth(columnIndex),
                CUSTOM_WIDTH : header.width,
                FREEZE : freezeFlag,
                CSPAN : hData.CSPAN,
                IS_CSPAN : hData.IS_CSPAN
            }

            if(hData.IS_CSPAN == 'true') {
                cspanFlag = true;
            }

            callFunction('GP_003', 'addData', [null, rowId, itemIndex, obj, true, cspanFlag]);

            voOriginalGridObj.deleteRow(rowId);
            headerData.push(obj);
        }

        callFunction('GP_003', 'setHeaderData', [headerData]);                    

        if(freezeRowId != undefined) {
            callFunction('GP_005', 'setFreezeValue', [freezeRowId]);
        }
    } else {
        for(var i = 0; i < oData.length; i++) {
            var obj = oData[i];
            var filterObj = showColumn.filter(x => x.COLUMN_ID == obj.COLUMN_ID);
            if(filterObj.length == 0) {
                continue;
            }

            var col = filterObj[0];
            var label = col.COLUMN_NAME;

            if(label == '#cspan') {
                continue;
            }

            var rowId = obj.gr_id;
            var itemIndex = voCustomGridObj.getRowsNum();
            var cspan = obj.CSPAN;

            callFunction('GP_003', 'addData', [null, rowId, itemIndex, obj, true]);

            voOriginalGridObj.deleteRow(rowId);
            headerData.push(obj);

            if(cspan != '') {
                var cspanId = cspan.split(',');

                if(cspanId.length == 0) {
                    continue;
                }

                for(var id of cspanId) {
                    var cspanObj = oData.filter(x => x.COLUMN_ID == id);

                    if(cspanObj.length == 0) {
                        continue;
                    }

                    for(var j = 0; j < cspanObj.length; j++) {
                        callFunction('GP_003', 'addData', [null, cspanObj[j].gr_id, itemIndex, cspanObj[j], true, true]);

                        voOriginalGridObj.deleteRow(cspanObj[j].gr_id);
                        headerData.push(cspanObj[j]);
                    }
                }

            }
        }
    }

    callFunction('GP_003', 'setHeaderData', [headerData]);
    callFunction('GP_003', 'setObj', ['ORIGINAL', $share.original]);
    callFunction('GP_007', 'doRenderPreviewGrid', [headerData]);
}


switch (name) {
    case "ADD_ALL_COLUMN":
        doAddColumn(true);
        break;

    case "ADD_COLUMN":
        doAddColumn(false);
        break;

    case "CLEAR_COLUMN":
        doClearColumn(false);
        break;

    case "CLEAR_ALL_COLUMN":
        doClearColumn(true);
        break;
}


var ids = voOriginalGridObj.getSelectedRowId();
if(flag) {
    ids = voOriginalGridObj.getAllRowIds();
}

if(ids) {
    var idsArray = ids.split(',');
    for(var i = 0; i < idsArray.length; i++) {
        var rowId = idsArray[i];
        var cspan = voOriginalGridObj.cells(rowId, voOriginalGridObj.getColIndexById('CSPAN')).getValue();
        var label = voOriginalGridObj.cells(rowId, voOriginalGridObj.getColIndexById('COLUMN_NAME')).getValue();

        if(label == '#cspan') {
            continue;
        }

        var obj = {
            COLUMN_NAME : label, 
            COLUMN_ID : voOriginalGridObj.cells(rowId, voOriginalGridObj.getColIndexById('COLUMN_ID')).getValue(),
            TYPE : voOriginalGridObj.cells(rowId, voOriginalGridObj.getColIndexById('TYPE')).getValue(),
            STANDARD_WIDTH : voOriginalGridObj.cells(rowId, voOriginalGridObj.getColIndexById('STANDARD_WIDTH')).getValue(),
            ALIGN : voOriginalGridObj.cells(rowId, voOriginalGridObj.getColIndexById('ALIGN')).getValue(),
            FREEZE : false,
            CSPAN : cspan
        }

        callFunction('GP_003', 'setHeaderData', [obj]);
        callFunction('GP_003', 'addData', [voCustomGridObj, rowId, voCustomGridObj.getRowsNum(), obj, true]);
        voOriginalGridObj.deleteRow(rowId);

        if(cspan != undefined && cspan != '') {
            var cspanIds = cspan.split(',');

            if(cspanIds.length == 0) {
                continue;
            }

            for(var id of cspanIds) {
                var cspanData = voOriginalGridObj.getAllDataObject().filter(x => x.COLUMN_ID == id);

                if(cspanData.length == 0) {
                    continue;
                }

                callFunction('GP_003', 'setHeaderData', [cspanData[0]]);
                callFunction('GP_003', 'addData', [voCustomGridObj, cspanData[0].gr_id, voCustomGridObj.getRowsNum(), cspanData[0], true, true]);
                voOriginalGridObj.deleteRow(cspanData[0].gr_id);
                i++;
            }
        }
    }
} else {
    Alert(Sepoa.cache.text.get('GP_004.MESSAGE_SELECT_ADD_COLUMN'));

    return;
}


var ids = voCustomGridObj.getSelectedRowId();
if(flag) {
    ids = voCustomGridObj.getAllRowIds();
}

if(ids) {
    var headers = [];
    var idsArray = ids.split(',');
    var cspanGridId = [];
    for(var i = 0; i < idsArray.length; i++) {
        rowId = idsArray[i];

        if(cspanGridId.includes(parseInt(rowId))) {
            continue;
        }

        var columnId = voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('COLUMN_ID')).getValue();
        var columnName = voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('COLUMN_NAME')).getValue();

        if(columnName == '#cspan') {
            continue;
        }

        var cspan = voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('CSPAN')).getValue();
        var itemIndex = voOriginalGridObj.getRowsNum();

        var obj = {
            COLUMN_NAME : voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('COLUMN_NAME')).getValue(), 
            COLUMN_ID : columnId,
            TYPE : voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('TYPE')).getValue(),
            STANDARD_WIDTH : voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('STANDARD_WIDTH')).getValue(),
            ALIGN : voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('ALIGN')).getValue(),
            FREEZE : voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('FREEZE')).getValue(),
            CSPAN : cspan
        }

        headers.push(obj);
        callFunction('GP_003', 'addData', [voOriginalGridObj, rowId, itemIndex, obj, false]);
        callFunction('GP_003', 'deleteData', [rowId]);

        if(cspan != undefined && cspan != '') {
            var cspanIds = cspan.split(',');

            if(cspanIds.length == 0) {
                continue;
            }

            for(var id of cspanIds) {
                var cspanData = voCustomGridObj.getAllDataObject().filter(x => x.COLUMN_ID == id);

                if(cspanData.length == 0) {
                    continue;
                }

                cspanGridId.push(cspanData[0].gr_id);
                headers.push(cspanData[0]);
                callFunction('GP_003', 'addData', [voOriginalGridObj, cspanData[0].gr_id, itemIndex, cspanData[0], false, true]);
                callFunction('GP_003', 'deleteData', [cspanData[0].gr_id]);

            }
        }
    }

    callFunction('GP_003', 'removeHeaderData', [headers]);
} else {
    Alert(Sepoa.cache.text.get('GP_004.MESSAGE_SELECT_DELETE_COLUMN'));

    return;
}


var ids = voCustomGridObj.getAllRowIds();

if(ids) {
    var headerData = [];
    var gridData = voCustomGridObj.getAllDataObject();
    var idsArray = ids.split(',');

    for(var i = 0; i < idsArray.length; i++) {
        var rowId = idsArray[i];
        var columnName = voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('COLUMN_NAME')).getValue();

        if(columnName == '#cspan') {
            continue;
        }

        var columnId = voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('COLUMN_ID')).getValue();
        var cspan = voCustomGridObj.cells(rowId, voCustomGridObj.getColIndexById('CSPAN')).getValue();
        var obj = gridData.filter(x => x.COLUMN_ID == columnId);

        if(obj.length > 0) {
            headerData.push(obj[0]);

            if(cspan != undefined && cspan != '') {
                var cspanIds = cspan.split(',');

                if(cspanIds.length == 0) {
                    continue;
                }

                for(var id of cspanIds) {
                    var cspanData = voCustomGridObj.getAllDataObject().filter(x => x.COLUMN_ID == id);

                    if(cspanData.length == 0) {
                        continue;
                    }


                    headerData.push(cspanData[0]);
                }
            }
        }
    }

    callFunction('GP_003', 'setHeaderData', [headerData]);
    callFunction('GP_005', 'doMoveColumn', [headerData]);
    callFunction('GP_006', 'doMoveColumn', [headerData]);
}
